48	function fmtUptime(seconds: number): string {
49	  if (!seconds || seconds <= 0) return "—";
50	  const d = Math.floor(seconds / 86400);
51	  const h = Math.floor((seconds % 86400) / 3600);
52	  const m = Math.floor((seconds % 3600) / 60);
53	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
54	}
