1133	  const cents = p.prorateCents ?? 0;
1134	  if (cents <= 0 || !job.serverId) return;
1135	
1136	  // Idempotency: skip if we already reversed this exact job.
1137	  const already = await db.auditLog.findFirst({
1138	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
1139	  });
1140	  if (already) return;
1141	
1142	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
1143	  if (!server) return;
1144	
1145	  try {
1146	    if (p.direction === "up") {
1147	      // Upgrade charge never delivered → refund the prorated charge.
1148	      await db.$transaction([
1149	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
1150	        db.walletTransaction.create({
1151	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
1152	        }),
1153	      ]);
1154	    } else if (p.direction === "down") {
1155	      // Downgrade credit was given but hardware unchanged → claw the credit back.
1156	      // Guarded so it can never drive the balance negative; if the customer already
1157	      // spent it, we log and leave it (best-effort — they keep a small windfall).
1158	      await db.$transaction(async (tx) => {
1159	        await debitWallet(tx, server.userId, cents);
1160	        await tx.walletTransaction.create({
1161	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
1162	        });
1163	      });
1164	    }
1165	    await db.auditLog.create({
1166	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
1167	    });
1168	  } catch (e: any) {
1169	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
1170	    await db.auditLog.create({
1171	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
1172	    }).catch(() => {});
1173	  }
1174	}
