1252	async function cleanupFailedProvision(serverId: string): Promise<void> {
1253	  if (SANDBOX) return;
1254	  // Capture whether it was a dedicated IP BEFORE release nulls the row's serverId.
1255	  const dedicated = await db.dedicatedIp.findUnique({ where: { serverId }, select: { id: true } });
1256	  await releaseDedicatedIp(serverId).catch((err) =>
1257	    console.error(`[worker] release dedicated IP on failed provision for ${serverId}`, err)
1258	  );
1259	  if (dedicated) {
1260	    await db.server.update({ where: { id: serverId }, data: { ipAddress: null } }).catch(() => {});
