1264	/**
1265	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
1266	 * killed worker leaves a job RUNNING forever, which permanently blocks the
1267	 * server's "one in-flight job" guard and strands it in a transitional state.
1268	 */
1269	async function reapStuckJobs() {
1270	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
1271	  for (const job of stuck) {
1272	    const retriable = job.attempts < MAX_ATTEMPTS;
1273	    await db.job.update({
1274	      where: { id: job.id },
1275	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
1276	    });
1277	    if (!retriable) {
1278	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
1279	      if (job.serverId) {
1280	        const s = await db.server.findUnique({ where: { id: job.serverId } });
1281	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
1282	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
1283	        }
1284	        // Same IP-leak cleanup the runJob catch-path does — a PROVISION reaped here
1285	        // (killed on its final attempt) would otherwise strand its dedicated IP +
1286	        // billable OVH vMAC forever (audit 2026-08-01).
1287	        if (job.type === "PROVISION") {
1288	          await cleanupFailedProvision(job.serverId).catch((err) =>
1289	            console.error(`[worker] cleanup failed provision (reap) ${job.id}`, err)
1290	          );
1291	        }
1292	      }
1293	    }
1294	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
1295	  }
1296	}
