/**
 * Tell the customer their server failed to provision. Before this, a terminal
 * PROVISION failure flipped the server to ERROR and sent NOTHING — the customer
 * paid, then sat on a dead screen with a red dot and no explanation. Persists a
 * short human reason on `Server.provisionError` (surfaced in the ERROR banner on
 * the detail page), drops an in-app notification, and emails them. Best-effort on
 * every leg — a failed notification must never mask the underlying job failure.
 *
 * `error` is the redacted Job.error; we keep a trimmed copy for the customer.
 */
async function notifyProvisionFailed(
  server: { id: string; userId: string; hostname: string },
  error: string,
): Promise<void> {
  // A concise, customer-facing reason. The raw Job.error can be a 2000-char stack;
  // the first line is almost always the meaningful message.
  const reason = (error.split("\n")[0] || error).trim().slice(0, 300);
  try {
    await db.server.update({ where: { id: server.id }, data: { provisionError: reason } });
  } catch (e) {
    console.error("[worker] persist provisionError failed", e);
  }
  await notify(
    server.userId,
    `We couldn't set up ${server.hostname}`,
    `Provisioning failed and our team has been notified. You can retry it or contact support from the server page.`,
    `/dashboard/servers/${server.id}`,
  );
  try {
    const { sendMail, emails } = await import("../lib/mailer");
    const user = await db.user.findUnique({ where: { id: server.userId }, select: { email: true } });
    if (user?.email) {
      const tpl = emails.provisionFailed({ hostname: server.hostname, reason });
      await sendMail({
        to: user.email,
        subject: tpl.subject,
        html: tpl.html,
        template: tpl.template,
        userId: server.userId,
        // No `kind` → always send. A paid-for server that failed to build is a
        // service-delivery failure the customer must hear about.
      });
    }
  } catch (e) {
    console.error("[worker] provision-failure email failed", e);
  }
}

