/**
 * Retry a FAILED NxCloud instance whose backing VM never came up. Re-enqueues a
 * PROVISION job on the same Server (the provision handler keeps any persisted
 * vmid, so a retry resumes rather than leaking a second VM) and moves both the
 * instance and its server back into the transitional PROVISIONING state so the
 * dashboard shows "setting up" instead of the failed card. Owner/admin only,
 * guarded to FAILED. Mirrors retryHostingProvision / retryProvision.
 */
export async function retryNxcloud(instanceId: string): Promise<NxCloudResult> {
  const user = await requireUser();
  const inst = await db.nxCloudInstance.findUnique({
    where: { id: instanceId },
    select: { userId: true, status: true, serverId: true },
  });
  if (!inst) return { error: "Not found." };
  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
  if (inst.status !== "FAILED") return { error: "This cloud isn’t in a failed state." };
  if (!inst.serverId) return { error: "No backing server to retry — please contact support." };
  // Don't double-enqueue if a job is already in flight on the backing server.
  const inflight = await db.job.count({
    where: { serverId: inst.serverId, status: { in: ["QUEUED", "RUNNING"] } },
  });
  if (inflight > 0) return { error: "A setup task is already running on this cloud." };

  await db.$transaction([
    db.nxCloudInstance.update({ where: { id: instanceId }, data: { status: "PENDING", error: null } }),
    db.server.update({ where: { id: inst.serverId }, data: { status: "PROVISIONING", provisionError: null } }),
    db.job.create({ data: { type: "PROVISION", serverId: inst.serverId } }),
  ]);
  await db.auditLog
    .create({ data: { userId: user.id, action: "nxcloud.retry_provision", detail: instanceId } })
    .catch(() => {});
  revalidatePath("/dashboard/nxcloud");
  return { ok: true };
}

